select is(tests.rls_exec('aec19468-1e39-5272-be8d-d29ff62c14d7'::uuid, $q$select 1 from (select public.rider_time_out('c4a259d0-1f1b-5ad3-91ea-3f12de964763') j) x where (j ->> 'deliveries')::int = 1
